bool down(std::size_t key) const noexcept { return key < Count ? held_[key] : false; }
bool pressed(std::size_t key) const noexcept { return key < Count ? pressed_[key] : false; }
bool released(std::size_t key) const noexcept { return key < Count ? released_[key] : false; }

void begin_frame() noexcept {
    for (std::size_t i = 0; i < Count; ++i) {
        pressed_[i] = false;
        released_[i] = false;
    }
    cancelled_ = false;
}

void set(std::size_t key, bool down, bool repeat = false) noexcept {
    if (key >= Count) return;
    if (down && repeat) return;
    const bool was = held_[key];
    if (down && !was) pressed_[key] = true;
    if (!down && was) released_[key] = true;
    held_[key] = down;
}

void capture(bool left, bool right, bool up, bool downHeld = false,
             bool spacePressed = false) noexcept {
    horizontal_.capture(left, right);
    clockwise_ = clockwise_ || up;
    soft_drop_ = downHeld;
    // A bool latch is enough here: it coalesces any number of captured
    // hard-drop edges into a single pending request. It is NOT a queue and
    // gives no physical exact-once guarantee; two presses captured before
    // one consume() still yield one hard_drop.
    hard_drop_ = hard_drop_ || spacePressed;
}

Intent consume() noexcept {
    Intent result{horizontal_.consume(), clockwise_, soft_drop_, hard_drop_};
    clockwise_ = false;
    hard_drop_ = false;
    return result;
}

void cancel() noexcept {
    for (std::size_t i = 0; i < Count; ++i) {
        released_[i] = released_[i] || held_[i];
        held_[i] = false;
        pressed_[i] = false;
    }
    cancelled_ = true;
}
